Set-Location -LiteralPath $PSScriptRoot
$msg = 'diagnostics: read the Twilio Alerts/Debugger log, read-only. The Messages API says whether Twilio RECEIVED a message; it says nothing about what happened when Twilio then POSTed it to our webhook. So when a message exists in Twilio and no Reply row exists in EvoSys, two very different failures look identical - Twilio never dispatched or could not reach us (11200, 11205, 15003), versus Twilio dispatched and our own guard_inbound refused it with a 403. Twilio records every FAILED webhook delivery in Monitor/Alerts with the error code, request URL and our response body, and reading that log is the only way to separate those two without guessing. GET /god/sms-trace/alerts/{org} returns timestamp, error code, HTTP status parsed from alert_text, request URL and method, our response body, log level and Twilio more_info link, filtered to the inbound webhook path over one time window. An empty log is reported as a RESULT rather than a gap, since Twilio only records failures. Deliberately not a monitoring system: one window, one filter, no storage, no scheduling, no alerting. Privacy bounded - request_variables carries the entire inbound payload including a family message, so only an allowlist leaves the endpoint and the body is truncated; request headers are never returned. God-only, behind the existing read-only trace access. No Twilio configuration, webhook, A2P registration, SMS send path or lead data touched.'
& "$PSScriptRoot\deploy.ps1" -Message $msg
Write-Output ("DEPLOY_EXIT=" + $LASTEXITCODE)
